  on conflict (node_id, depth, level, format) do update
    set body = excluded.body, generated = excluded.generated, reviewed = excluded.reviewed
    where content.body is distinct from excluded.body
       or content.generated is distinct from excluded.generated
       or content.reviewed is distinct from excluded.reviewed
  returning node_id
)
delete from content
where node_id in (select node_id from master)
  and not (depth = 'research' and level = 'advanced' and format = 'read');

-- Curated, human-reviewed quiz — same set served at every level.
with q as (
  select $tc_quiz$[
    {"id":"q1","type":"mcq","prompt":"Eric Hobsbawm's influential periodization of a 'short twentieth century' runs between which two dates?","options":["1900 and 2000","1914 and 1991","1870 and 1945","1917 and 1989"],"answerIndex":1,"explanation":"Hobsbawm framed a 'short twentieth century' from 1914 (the outbreak of the First World War) to 1991 (the dissolution of the Soviet Union) — an epoch defined by the rise and fall of the October Revolution and the world wars around it."},
    {"id":"q2","type":"mcq","prompt":"George Kennan called which event 'the great seminal catastrophe of this century'?","options":["The First World War","The Great Depression","The Second World War","The Russian Revolution"],"answerIndex":0,"explanation":"Kennan's phrase for the First World War became standard because its causal chains run everywhere — to the Russian Revolution, the Versailles resentments, fascism, and, through the second war it made possible, the nuclear age."},
    {"id":"q3","type":"mcq","prompt":"The single largest famine in recorded history, discussed in the article, resulted from:","options":["Stalin's collectivization and the Ukrainian Holodomor","the Bengal famine of 1943","China's Great Leap Forward (1958–62)","the Irish Potato Famine"],"answerIndex":2,"explanation":"The article estimates the Great Leap Forward famine at 30–45 million deaths — the largest in recorded history. (The Holodomor, on the order of four million, was also catastrophic but smaller.)"},
    {"id":"q4","type":"mcq","prompt":"Which best captures the article's central interpretive claim (its 'instrumental synthesis') about the century?","options":["Technology made the century steadily better","The same amplified capabilities — the bureaucratic state, industry, mass communication, science — produced both its best and its worst outcomes, with institutions deciding which","The century's violence proves that progress is an illusion","Ideology, not technology, explains everything that happened"],"answerIndex":1,"explanation":"The article argues the century massively amplified human capability, which is morally symmetrical: where power was accountable and constrained, capability became welfare; where a single party or doctrine captured the amplified state, its worst pages were written."},
    {"id":"q5","type":"open","prompt":"The article insists a serious history must 'hold both ledgers open at once.' What are the two ledgers, and what is the relationship the article proposes between them?","rubric":"The two ledgers are (1) unprecedented organized violence — the world wars, the Holocaust and other genocides, the Stalinist and Maoist famines and terrors, and the wars of decolonization (roughly 150–200 million dead) — and (2) unprecedented gains in human welfare — life expectancy roughly doubling, child mortality collapsing, smallpox eradicated, majority literacy, population quadrupling while real incomes rose. The proposed relationship is instrumental: the SAME instruments (the powerful bureaucratic state, industrial technology, mass mobilization, and science) wrote both ledgers; whether amplified capability became welfare or catastrophe depended on whether power was constrained and plural or captured by a single party/leader/doctrine."},
    {"id":"q6","type":"open","prompt":"What does the article mean by 'total war', and how did the First World War inaugurate it?","rubric":"Total war means the mobilization of entire economies, populations, and imaginations for the war effort — not just armies. WWI inaugurated it: states that had taken ~5–10% of national income now commandeered around half; they rationed food, conscripted labor, directed industry, systematically propagandized, and policed dissent, building administrative capacities that later welfare states and police states alike inherited. Women entered the workforce and won the vote in its wake; the distinction between soldier and civilian eroded (culminating, by WWII, in a majority-civilian death toll)."}
  ]$tc_quiz$::jsonb as questions
)
insert into quizzes (node_id, level, questions, generated)
select 'history/20th-century-history', lvl, q.questions, true
from q, (values ('easy'), ('advanced'), ('expert')) as l(lvl)
on conflict (node_id, level) do update
  set questions = excluded.questions, generated = excluded.generated;
